DELIMITER $$
CREATE TRIGGER `after_purchase_insert` AFTER INSERT ON `cutlery_purchase_items` FOR EACH ROW BEGIN
    DECLARE purchase_date_val DATE;
    DECLARE purchase_id_val VARCHAR(20);
    
    SELECT purchase_date, purchase_id INTO purchase_date_val, purchase_id_val 
    FROM cutlery_purchases 
    WHERE id = NEW.purchase_id;
    
    -- Add stock to Stores
    VALUES (
        1,
        NEW.asset_id,
        NEW.quantity,
        'PURCHASE',
        NEW.purchase_id,
        purchase_id_val,
        purchase_date_val
    );
    
    VALUES (1, NEW.asset_id, NEW.quantity)
    ON DUPLICATE KEY UPDATE 
    quantity = quantity + NEW.quantity,
    updated_at = CURRENT_TIMESTAMP;
END
$$
DELIMITER ;

