--
-- Triggers `payment_history`
--
DELIMITER $$
CREATE TRIGGER `trg_payment_delete` AFTER DELETE ON `payment_history` FOR EACH ROW BEGIN
  DECLARE total_paid DECIMAL(10,2);

  SET total_paid = (
    SELECT IFNULL(SUM(amount), 0)
    FROM payment_history
    WHERE purchase_id = OLD.purchase_id
  );

  UPDATE purchases
  SET 
    paid_amount = total_paid,
    payment_status = CASE 
      WHEN total_paid >= total_with_vat THEN 'Paid'
      WHEN total_paid > 0 THEN 'Partially Paid'
      ELSE 'Non-Paid'
    END
  WHERE id = OLD.purchase_id;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_payment_insert` AFTER INSERT ON `payment_history` FOR EACH ROW BEGIN
  DECLARE total_paid DECIMAL(10,2);

  SET total_paid = (
    SELECT IFNULL(SUM(amount), 0)
    FROM payment_history
    WHERE purchase_id = NEW.purchase_id
  );

  UPDATE purchases
  SET 
    paid_amount = total_paid,
    payment_status = CASE 
      WHEN total_paid >= total_with_vat THEN 'Paid'
      WHEN total_paid > 0 THEN 'Partially Paid'
      ELSE 'Non-Paid'
    END
  WHERE id = NEW.purchase_id;
END
$$
DELIMITER ;
